# Global variables for search workers to avoid pickling the index multiple times
_global_index = None

def _search_init(index):
    global _global_index
    _global_index = index

def _search_worker(query_data):
    query, top_k = query_data
    # Use the sequential search implementation on the global index
    return sequential.search_sequential(query, _global_index, top_k, None)

def batch_search_parallel(queries, index, top_k=10, num_workers=None, documents=None):
    """
    Perform batch search in parallel.
    """
    start_time = time.perf_counter()

    if num_workers is None:
        num_workers = multiprocessing.cpu_count()

    # Prepare query data for workers
    query_items = [(q, top_k) for q in queries]

    # Use initializer to share index via copy-on-write or single pickle
    with multiprocessing.Pool(processes=num_workers, initializer=_search_init, initargs=(index,)) as pool:
        results = pool.map(_search_worker, query_items)

    # Patch titles if documents were provided
    if documents:
        doc_titles = {d.doc_id: d.title for d in documents}
        for res_list in results:
            for res in res_list:
                if res.doc_id in doc_titles:
                    res.title = doc_titles[res.doc_id]

    elapsed = time.perf_counter() - start_time
    return results, elapsed
